function merge(saved){const next=structuredClone(base);Object.keys(next).forEach(k=>{if(saved?.[k]!==undefined)next[k]=saved[k]});const oshakati=next.routes.find(r=>r.id==='rte_oshakati');if(oshakati&&num(oshakati.distance)===710){oshakati.name='Windhoek ↔ Oshakati';oshakati.distance=1420;oshakati.notes='710 km each way; 36 pallets beer / empty returns'}next.trips.filter(t=>t.routeId==='rte_oshakati'&&num(t.distance)===710).forEach(t=>{t.distance=1420;if(num(t.startKm)&&num(t.endKm)===num(t.startKm)+710)t.endKm=num(t.startKm)+1420});next.version=2;return next}
