function options(type){return {truck:db.trucks.map(x=>[x.id,x.registration]),trailer:db.trailers.map(x=>[x.id,x.registration]),driver:db.drivers.map(x=>[x.id,x.name]),client:db.clients.map(x=>[x.id,x.name]),route:db.routes.map(x=>[x.id,x.name]),trip:db.trips.map(x=>[x.id,`${x.number} · ${route(x.routeId)}`]),invoice:db.invoices.filter(x=>invoiceBalance(x)>.005).map(x=>[x.id,`${x.number} · ${client(x.clientId)} · ${money(invoiceBalance(x))} due`])}[type]||[]}
function openForm(type,prefill={}){formType=type;const list=forms[type];if(!list)return notify(`Open ${type} from its linked workflow`);$('modalTitle').textContent=`Add ${type}`;$('entryForm').innerHTML=`<div class="form-grid">${list.map(([key,label,kind,def,vals])=>{const value=prefill[key]??def??'',opts=kind==='select'?(vals||[]).map(v=>[String(v),String(v)]):options(kind);if(opts.length)return `<div class="field"><label>${label}</label><select name="${key}"><option value="">Select…</option>${opts.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;if(kind==='textarea')return `<div class="field full"><label>${label}</label><textarea name="${key}" rows="3">${esc(value)}</textarea></div>`;return `<div class="field"><label>${label}</label><input name="${key}" type="${kind}" step="any" value="${esc(value)}"></div>`}).join('')}<div class="form-actions"><button type="button" class="ghost" id="cancelForm">Cancel</button><button class="primary">Save & link record</button></div></div>`;$('modal').classList.remove('hidden');$('cancelForm').onclick=()=>$('modal').classList.add('hidden')}
function saveForm(e){e.preventDefault();const o={id:uid(formType)};new FormData($('entryForm')).forEach((v,k)=>o[k]=v);['tons','pallets','startKm','income','litres','price','odometer','cost','nextService','fittedKm','currentKm','amount','days','overtime','base','incentive','deductions','distance','rate','terms','loadLat','loadLon','offloadLat','offloadLon','approachKm','arrivalKm'].forEach(k=>{if(k in o)o[k]=num(o[k])});if(o.crossBorder)o.crossBorder=o.crossBorder==='true';if('roundTrip' in o)o.roundTrip=o.roundTrip==='true';const map={trip:'trips',diesel:'diesel',expense:'expenses',tripIssue:'tripIssues',payment:'payments',inspection:'inspections',incident:'incidents',permit:'permits',maintenance:'maintenance',tyre:'tyres',invoice:'invoices',advance:'advances',payroll:'payroll',client:'clients',route:'routes'},key=map[formType];if(formType==='trip'){o.number=`AT-${1000+db.trips.length+1}`;o.stage={Planned:1,Loading:2,'In transit':3,Delivered:4}[o.status]||1;o.distance=get('routes',o.routeId).distance||0;o.dieselCost=o.tolls=o.allowance=o.other=0;o.pod=false;o.approved=false;o.settlementStatus='Pending';get('trucks',o.truckId).status='Reserved';get('drivers',o.driverId).status='Assigned'}if(formType==='diesel'){o.verified=false;const t=get('trips',o.tripId);if(t.id)t.dieselCost=sum(linked('diesel','tripId',t.id),x=>num(x.litres)*num(x.price))+num(o.litres)*num(o.price)}if(formType==='expense'){o.status=o.receiptNo?'Review':'Receipt missing';o.reimbursable=true}if(formType==='tripIssue')o.status='Open';if(formType==='invoice'){o.status='Unpaid';o.paidAmount=0;o.balance=o.amount}if(formType==='payment'){const inv=get('invoices',o.invoiceId),balance=invoiceBalance(inv);if(!inv.id||o.amount<=0)return notify('Select an invoice and enter a valid payment amount');if(o.amount>balance+.005)return notify(`Payment exceeds the outstanding balance of ${money(balance)}`)}if(formType==='inspection'){o.items={tyres:true,lights:true,brakes:true,fluids:true,documents:true,load:true};o.score=o.defects?80:100;o.status=o.defects?'Failed':'Passed'}if(formType==='incident')o.status='Open';if(formType==='permit')o.status='Active';db[key].unshift(o);if(formType==='payment')refreshInvoiceStatus(get('invoices',o.invoiceId));$('modal').classList.add('hidden');commit(formType==='payment'?`Payment of ${money(o.amount)} recorded for ${get('invoices',o.invoiceId).number}`:`${formType} record created`,formType,o.id)}
function advanceTrip(id){const t=get('trips',id);if(t.stage===4&&!t.pod)return notify('Upload POD before invoicing');if(t.stage<5){t.stage++;t.status={2:'Loading',3:'In transit',4:'Delivered',5:'Invoiced'}[t.stage];if(t.stage===3){get('trucks',t.truckId).status='On trip';get('drivers',t.driverId).status='On trip'}if(t.stage===4)db.tasks.unshift({id:uid('task'),title:`Upload POD for ${t.number}`,ownerRole:'Driver',linkedType:'trip',linkedId:t.id,due:today(),priority:'High',status:'Open'});if(t.stage===5){const inv={id:uid('inv'),number:`INV-${1000+db.invoices.length+1}`,date:today(),clientId:t.clientId,tripId:t.id,amount:t.income,due:'',status:'Unpaid'};db.invoices.unshift(inv);t.invoiceId=inv.id;get('trucks',t.truckId).status='Available';get('drivers',t.driverId).status='Available'}}commit(`${t.number} moved to ${t.status}`,'trip',t.id)}
function openTrip(id){const t=get('trips',id),fuel=linked('diesel','tripId',id),expenses=linked('expenses','tripId',id),issues=linked('tripIssues','tripId',id),s=tripSettlement(t),m=s.fuel;$('modalTitle').textContent=`${t.number} · ${route(t.routeId)}`;$('entryForm').innerHTML=`<div class="split-3"><div><h3>Assignment</h3><p>${client(t.clientId)}<br>${truck(t.truckId)} / ${trailer(t.trailerId)}<br>${driver(t.driverId)}</p></div><div><h3>Diesel performance</h3><p>${m.ready?`${m.kmPerL.toFixed(2)} km/L<br>${m.litresPerKm.toFixed(3)} L/km<br>${m.litresPer100Km.toFixed(1)} L/100 km`:'Awaiting distance and diesel'}<br>${fuel.length} slip(s)</p></div><div><h3>Driver settlement</h3><p>Incentive ${money(s.incentive)}${s.rate?`<br><small>${m.distance.toLocaleString()} km × ${money(s.rate)}/km</small>`:''}<br>Approved expenses ${money(s.reimbursable)}<br>Advances ${money(s.advances)}<br><b>Amount due ${money(s.due)}</b></p></div></div><h3>Route expenses & receipts</h3>${expenses.length?expenses.map(x=>`<div class="approval"><span><b>${esc(x.category)}</b> · ${money(x.amount)}<small>${esc(x.supplier||'')} · Receipt: ${esc(x.receiptNo||'MISSING')}</small></span><span>${badge(x.status)} ${x.status==='Review'&&['admin','manager','finance'].includes(role)?`<button type="button" class="link-button approve-trip-expense" data-id="${x.id}">Approve</button>`:''}</span></div>`).join(''):'<div class="empty">No route expenses captured</div>'}<h3>What went wrong on this trip</h3>${issues.length?issues.map(x=>`<div class="policy ${x.status==='Open'?'critical':''}"><h3>${esc(x.type)} · ${esc(x.location||'Location not recorded')}</h3><p>${esc(x.description)}<br><b>Action:</b> ${esc(x.action||'Pending')} · Cost ${money(x.cost)}</p></div>`).join(''):'<div class="empty">No trip problems reported</div>'}<div class="form-actions"><button type="button" class="ghost" id="cancelForm">Close</button><button type="button" class="ghost" id="addExpenseModal">Add expense</button><button type="button" class="ghost" id="addIssueModal">Report problem</button><button type="button" class="primary" id="advanceFromModal">Advance workflow</button></div>`;$('modal').classList.remove('hidden');$('cancelForm').onclick=()=>$('modal').classList.add('hidden');$('addExpenseModal').onclick=()=>openForm('expense',{tripId:id,truckId:t.truckId,driverId:t.driverId});$('addIssueModal').onclick=()=>openForm('tripIssue',{tripId:id,truckId:t.truckId,driverId:t.driverId});document.querySelectorAll('.approve-trip-expense').forEach(b=>b.onclick=()=>{get('expenses',b.dataset.id).status='Approved';commit(`Receipt approved for ${t.number}`,'expense',b.dataset.id);openTrip(id)});$('advanceFromModal').onclick=()=>{$('modal').classList.add('hidden');advanceTrip(t.id)}}
function rateResult(){const v=id=>num($(id).value),distance=v('rcDistance'),litres=distance/Math.max(.1,v('rcKml')),diesel=litres*v('rcDiesel'),standing=v('rcWaiting')*db.settings.standingFee,cost=diesel+v('rcDriver')+v('rcTolls')+v('rcWear')+v('rcOther')+standing,margin=Math.min(90,v('rcMargin'))/100,rate=cost/(1-margin),vat=rate*db.settings.vat/100;$('rateResult').innerHTML=`<div class="metric-line"><span>Diesel required</span><b>${litres.toFixed(1)} L</b></div><div class="metric-line"><span>Diesel cost</span><b>${money(diesel)}</b></div><div class="metric-line"><span>Standing charges</span><b>${money(standing)}</b></div><div class="metric-line"><span>Total cost</span><b>${money(cost)}</b></div><div class="metric-line"><span>Rate excl. VAT</span><b class="positive">${money(rate)}</b></div><div class="metric-line"><span>VAT</span><b>${money(vat)}</b></div><div class="metric-line"><span>Quote incl. VAT</span><b>${money(rate+vat)}</b></div><div class="metric-line"><span>Expected profit</span><b>${money(rate-cost)}</b></div>`}
function openInvoice(id){const i=get('invoices',id);refreshInvoiceStatus(i);const payments=linked('payments','invoiceId',id);$('modalTitle').textContent=`${i.number} · ${client(i.clientId)}`;$('entryForm').innerHTML=`<div class="split-3"><div><span>Invoice amount</span><h3>${money(i.amount)}</h3><p>${esc(i.date)} · Due ${esc(i.due||'—')}</p></div><div><span>Received</span><h3 class="positive">${money(invoicePaid(id))}</h3><p>${payments.length} payment(s)</p></div><div><span>Outstanding</span><h3>${money(invoiceBalance(i))}</h3><p>${badge(i.status)}</p></div></div><h3>Payment history</h3>${payments.length?payments.map(p=>`<div class="approval"><span><b>${money(p.amount)}</b><small>${esc(p.date)} · ${esc(p.method)} · ${esc(p.reference||'No reference')}</small></span><span>${esc(p.proof||'No proof reference')}</span></div>`).join(''):'<div class="empty">No payments recorded</div>'}<div class="form-actions"><button type="button" class="ghost" id="cancelForm">Close</button>${invoiceBalance(i)>.005?'<button type="button" class="primary" id="recordPayment">Record payment</button>':''}</div>`;$('modal').classList.remove('hidden');$('cancelForm').onclick=()=>$('modal').classList.add('hidden');if($('recordPayment'))$('recordPayment').onclick=()=>openForm('payment',{invoiceId:id,amount:invoiceBalance(i)})}
function download(name,data,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function exportWorkbook(kind){const definitions={trips:{title:'Trips and Loads',columns:[['number','Trip'],['date','Date','date'],['route','Route'],['client','Client'],['truck','Truck'],['trailer','Trailer'],['driver','Driver'],['load','Load'],['tons','Tons','number'],['pallets','Pallets','number'],['distance','Distance km','number'],['income','Income','currency'],['dieselCost','Diesel Cost','currency'],['otherCosts','Other Costs','currency'],['profit','Contribution','currency'],['status','Status'],['pod','POD']],rows:db.trips.map(t=>({...t,route:route(t.routeId),client:client(t.clientId),truck:truck(t.truckId),trailer:trailer(t.trailerId),driver:driver(t.driverId),otherCosts:num(t.tolls)+num(t.allowance)+num(t.other),profit:tripProfit(t),pod:t.pod?'Received':'Missing'}))},invoice:{title:'Invoices and Debtors',columns:[['number','Invoice'],['date','Invoice Date','date'],['client','Client'],['trip','Trip'],['amount','Invoice Amount','currency'],['received','Received','currency'],['balance','Outstanding','currency'],['due','Due Date','date'],['status','Status']],rows:db.invoices.map(i=>({...i,client:client(i.clientId),trip:get('trips',i.tripId).number||'',received:invoicePaid(i.id),balance:invoiceBalance(i)}))},diesel:{title:'Diesel Control',columns:[['date','Date','date'],['trip','Trip'],['truck','Truck'],['driver','Driver'],['litres','Litres','number'],['price','Price per Litre','currency'],['total','Total Cost','currency'],['odometer','Odometer','number'],['supplier','Supplier'],['slip','Slip'],['verified','Verified']],rows:db.diesel.map(x=>({...x,trip:get('trips',x.tripId).number||'',truck:truck(x.truckId),driver:driver(x.driverId),total:num(x.litres)*num(x.price),verified:x.verified?'Yes':'No'}))}};let d=definitions[kind];if(!d){const key={tyre:'tyres',advance:'advances',expense:'expenses'}[kind]||kind,rows=db[key]||[];if(!rows.length)return notify('No data to export');const keys=[...new Set(rows.flatMap(Object.keys))];d={title:kind[0].toUpperCase()+kind.slice(1),columns:keys.filter(k=>typeof rows.find(x=>x[k]!=null)?.[k]!=='object').map(k=>[k,k.replace(/([A-Z])/g,' $1').replace(/^./,c=>c.toUpperCase())]),rows}}if(!d.rows.length)return notify('No data to export');const body={title:d.title,columns:d.columns.map(([key,label,type])=>({key,label,type})),rows:d.rows};try{const res=await fetch(`/api/export/${encodeURIComponent(kind)}`,{method:'POST',headers:{Authorization:`Bearer ${authToken}`,'Content-Type':'application/json'},body:JSON.stringify(body)});if(!res.ok){const x=await res.json().catch(()=>({}));throw Error(x.error||'Excel export failed')}const blob=await res.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${kind}-${today()}.xlsx`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify('Excel workbook downloaded')}catch(e){notify(e.message)}}
const exportCsv=exportWorkbook;
function backup(){download(`Angermund_Transport_Operations_${today()}.json`,JSON.stringify(db,null,2))}
function restore(file){const reader=new FileReader();reader.onload=()=>{try{const n=JSON.parse(reader.result);if(!n.trips||!n.trucks)throw Error('Invalid transport backup');db=merge(n);commit('Backup restored')}catch(e){notify(e.message)}};reader.readAsText(file)}
function notify(msg){$('toast').textContent=msg;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2400)}
async function gpsCheckIn(){if(!navigator.geolocation)return notify('GPS is not supported on this device');const t=db.trips.find(x=>x.driverId===currentDriver()&&!['Closed','Invoiced'].includes(x.status));navigator.geolocation.getCurrentPosition(async p=>{try{await api('/api/gps',{method:'POST',body:{vehicleId:t?.truckId||'unassigned',driverId:currentDriver(),tripId:t?.id||null,latitude:p.coords.latitude,longitude:p.coords.longitude,speed:(p.coords.speed||0)*3.6,heading:p.coords.heading||0,accuracy:p.coords.accuracy}});notify('Live GPS check-in recorded')}catch(e){notify(e.message)}},e=>notify(`GPS unavailable: ${e.message}`),{enableHighAccuracy:true,timeout:15000})}
async function loadTracking(){try{[liveGps,geofences]=await Promise.all([api('/api/gps/latest'),api('/api/geofences')]);if(page==='tracking')render()}catch(e){notify(e.message)}}
async function loadNotifications(){try{serverNotifications=await api('/api/notifications');$('notificationCount').textContent=serverNotifications.filter(x=>!x.read).length;if(page==='notifications')render()}catch{}}
function drawMap(){if(page!=='tracking'||!window.L||!$('fleetMap'))return;if(mapInstance){mapInstance.remove();mapInstance=null}mapInstance=L.map('fleetMap').setView([-22.57,17.08],6);if(L.maplibreGL)L.maplibreGL({style:providerConfig.mapStyle||'https://tiles.openfreemap.org/styles/liberty'}).addTo(mapInstance);else $('fleetMap').classList.add('map-provider-fallback');geofences.forEach(f=>L.circle([f.latitude,f.longitude],{radius:f.radiusM,color:'#ffbd4a',fillOpacity:.08}).bindPopup(`<b>${esc(f.name)}</b><br>${num(f.radiusM)} m`).addTo(mapInstance));liveGps.forEach(p=>L.marker([p.latitude,p.longitude]).bindPopup(`<b>${esc(truck(p.vehicleId))}</b><br>${num(p.speed).toFixed(0)} km/h`).addTo(mapInstance));if(liveGps.length)mapInstance.fitBounds(liveGps.map(p=>[p.latitude,p.longitude]),{padding:[40,40],maxZoom:14})}
async function addGeofence(){const name=prompt('Geofence name');if(!name)return;const latitude=Number(prompt('Latitude')),longitude=Number(prompt('Longitude')),radiusM=Number(prompt('Radius in metres','500'));if(!Number.isFinite(latitude)||!Number.isFinite(longitude))return notify('Valid coordinates required');try{await api('/api/geofences',{method:'POST',body:{name,latitude,longitude,radiusM}});await loadTracking()}catch(e){notify(e.message)}}
async function enablePush(){if(!('serviceWorker'in navigator)||!('PushManager'in window))return notify('Push notifications not supported');try{const permission=await Notification.requestPermission();if(permission!=='granted')return notify('Push permission was not granted');if(!providerConfig.vapidPublicKey)return notify('VAPID keys must be configured on the server');const reg=await navigator.serviceWorker.ready,key=Uint8Array.from(atob(providerConfig.vapidPublicKey.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0)),sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});await api('/api/push/subscribe',{method:'POST',body:sub});notify('Browser push enabled')}catch(e){notify(e.message)}}
async function uploadScan(file){const fd=new FormData();fd.append('document',file);try{const job=await api('/api/documents/scan',{method:'POST',body:fd});notify(`OCR started: ${job.id}. Results will require review.`)}catch(e){notify(e.message)}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="expense"],[data-action="tripIssue"],.open-invoice,.pay-invoice');if(!b)return;if(b.classList.contains('open-invoice'))return openInvoice(b.dataset.id);if(b.classList.contains('pay-invoice')){const i=get('invoices',b.dataset.id);return openForm('payment',{invoiceId:i.id,amount:invoiceBalance(i)})}const t=get('trips',b.dataset.trip);openForm(b.dataset.action,{tripId:t.id,truckId:t.truckId,driverId:t.driverId})});
function wire(){document.querySelectorAll('.route-zones').forEach(b=>b.onclick=()=>openRouteZones(b.dataset.id));if($('driverPreviewSelect'))$('driverPreviewSelect').onchange=e=>{driverPreviewId=e.target.value;render()};if(page==='driverAccounts'&&role==='admin')wireDriverAccounts();document.querySelectorAll('.driver-next').forEach(b=>b.onclick=()=>{const t=get('trips',b.dataset.trip);if(t.id)driverMainStep(t)});document.querySelectorAll('[data-driver-quick]').forEach(b=>b.onclick=()=>{const t=get('trips',b.dataset.trip);if(!t.id)return;if(b.dataset.driverQuick==='scan')driverCapture('receipt',file=>openDriverSmartSlip(t,file));else if(b.dataset.driverQuick==='diesel')driverCapture('diesel',file=>openDriverDiesel(t,file));else if(b.dataset.driverQuick==='expense')driverCapture('expense',file=>openDriverExpense(t,file));else if(b.dataset.driverQuick==='problem')openDriverProblem(t)});if($('driverHelpBtn'))$('driverHelpBtn').onclick=openDriverHelp;if(role==='driver'&&page==='driverPortal'){if(!sessionStorage.getItem('driver_gps_session')){sessionStorage.setItem('driver_gps_session','1');setTimeout(gpsCheckIn,500)}setTimeout(flushDriverJobs,800)}document.querySelectorAll('.nav-to').forEach(b=>b.onclick=()=>go(b.dataset.page));document.querySelectorAll('.action').forEach(b=>b.onclick=()=>{const a=b.dataset.action,id=b.dataset.trip,t=get('trips',id);if(a==='newTrip')openForm('trip');else if(a==='inspection')openForm('inspection',{tripId:id,truckId:t.truckId,driverId:t.driverId});else if(a==='diesel')openForm('diesel',{tripId:id,truckId:t.truckId,driverId:t.driverId});else if(a==='incident')openForm('incident',{tripId:id});else if(a==='pod'){t.pod=true;db.tasks.filter(x=>x.linkedId===id&&/POD/.test(x.title)).forEach(x=>x.status='Completed');commit(`POD linked to ${t.number}`,'trip',id)}else if(a==='checkIn')gpsCheckIn();else if(a==='scan')$('scanInput').click()});document.querySelectorAll('.add-record').forEach(b=>b.onclick=()=>openForm(b.dataset.type));document.querySelectorAll('.advance-trip').forEach(b=>b.onclick=()=>advanceTrip(b.dataset.id));document.querySelectorAll('.open-trip').forEach(b=>b.onclick=()=>openTrip(b.dataset.id));document.querySelectorAll('.complete-task').forEach(b=>b.onclick=()=>{get('tasks',b.dataset.id).status='Completed';commit('Task completed','task',b.dataset.id)});document.querySelectorAll('.approval-action').forEach(b=>b.onclick=()=>{get('approvals',b.dataset.id).status=b.dataset.status;commit(`Request ${b.dataset.status.toLowerCase()}`,'approval',b.dataset.id)});document.querySelectorAll('.export').forEach(b=>b.onclick=()=>exportCsv(b.dataset.kind));const s=$('tripSearch');if(s)s.oninput=()=>{$('tripResults').innerHTML=tripTable(db.trips.filter(t=>[t.number,route(t.routeId),client(t.clientId),truck(t.truckId),driver(t.driverId)].join(' ').toLowerCase().includes(s.value.toLowerCase())))};if(page==='tracking'){setTimeout(drawMap);if($('refreshTracking'))$('refreshTracking').onclick=loadTracking;if($('addGeofence'))$('addGeofence').onclick=addGeofence}if(page==='notifications'){if($('refreshNotifications'))$('refreshNotifications').onclick=loadNotifications;if($('enablePush'))$('enablePush').onclick=enablePush;if($('testAlerts'))$('testAlerts').onclick=async()=>{try{await api('/api/notifications/test',{method:'POST'});await loadNotifications()}catch(e){notify(e.message)}};document.querySelectorAll('.read-notification').forEach(b=>b.onclick=async()=>{await api(`/api/notifications/${b.dataset.id}/read`,{method:'PATCH'});await loadNotifications()})}if(page==='rates'){document.querySelectorAll('#rateForm input,#rateForm select').forEach(x=>x.oninput=rateResult);$('rcRoute').onchange=()=>{$('rcDistance').value=get('routes',$('rcRoute').value).distance;rateResult()};rateResult();$('saveQuote').onclick=()=>{db.tasks.unshift({id:uid('task'),title:`Prepare quotation for ${route($('rcRoute').value)}`,ownerRole:'Finance',linkedType:'route',linkedId:$('rcRoute').value,due:today(),priority:'Normal',status:'Open'});commit('Quotation task created')}}const ss=$('saveSettings');if(ss)ss.onclick=()=>{db.settings.dieselPrice=num($('setDiesel').value);db.settings.vat=num($('setVat').value);db.settings.targetKml=num($('setKml').value);db.settings.standingFee=num($('setStanding').value);commit('Operating defaults updated')};const sd=$('saveDriver');if(sd)sd.onclick=()=>{db.settings.currentDriver=$('setDriver').value;commit('Driver identity updated')};if($('downloadBackup'))$('downloadBackup').onclick=backup;if($('restoreBackup'))$('restoreBackup').onclick=()=>{$('fileInput').dataset.kind='restore';$('fileInput').click()};if($('resetData'))$('resetData').onclick=()=>{if(confirm('Reset all demonstration data?')){db=structuredClone(base);commit('Demonstration data reset')}}}
function connectEvents(){const events=new EventSource(`/api/events?token=${encodeURIComponent(authToken)}`);events.addEventListener('gps',e=>{const p=JSON.parse(e.data),i=liveGps.findIndex(x=>x.vehicleId===p.vehicleId);if(i<0)liveGps.push(p);else liveGps[i]=p;if(page==='tracking')render()});events.addEventListener('notification',e=>{serverNotifications.unshift(JSON.parse(e.data));$('notificationCount').textContent=serverNotifications.filter(x=>!x.read).length;if(page==='notifications')render()});events.addEventListener('state',async()=>{try{const state=await api('/api/state');if(state.payload&&Object.keys(state.payload).length){db=merge(state.payload);localStorage.setItem(STORE,JSON.stringify(db));render()}}catch{}});events.onerror=()=>{} }
async function boot(){try{const [{user},state,config]=await Promise.all([api('/api/session'),api('/api/state'),api('/api/config')]);sessionUser=user;role=user.role;providerConfig=config;if(user.driverId)db.settings.currentDriver=user.driverId;if(state.payload&&Object.keys(state.payload).length)db=merge(state.payload);else if(['admin','manager','dispatcher','workshop','finance'].includes(role))await api('/api/state',{method:'PUT',body:db});localStorage.setItem(STORE,JSON.stringify(db));$('loginScreen').classList.add('hidden');page=role==='driver'?'driverPortal':'command';await Promise.all([loadTracking(),loadNotifications()]);connectEvents();render()}catch(e){logout();$('loginError').textContent=e.message}}
$('menuBtn').onclick=()=>$('sidebar').classList.toggle('open');$('closeModal').onclick=()=>$('modal').classList.add('hidden');$('entryForm').onsubmit=saveForm;$('quickTripBtn').onclick=()=>openForm('trip');$('backupBtn').onclick=backup;$('notificationBtn').onclick=()=>go('notifications');$('roleSelect').onchange=()=>{$('roleSelect').value=role};$('fileInput').onchange=()=>{if($('fileInput').files[0]&&$('fileInput').dataset.kind==='restore')restore($('fileInput').files[0]);$('fileInput').value=''};$('scanInput').onchange=()=>{const f=$('scanInput').files[0];if(f)uploadScan(f);$('scanInput').value=''};$('loginForm').onsubmit=async e=>{e.preventDefault();$('loginError').textContent='';try{const result=await api('/api/auth/login',{method:'POST',body:{email:$('loginEmail').value,password:$('loginPassword').value}});authToken=result.token;localStorage.setItem('angermund_token',authToken);await boot()}catch(err){$('loginError').textContent=err.message}};window.onclick=e=>{if(e.target===$('modal'))$('modal').classList.add('hidden')};window.addEventListener('online',flushDriverJobs);if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js');localStorage.setItem(STORE,JSON.stringify(db));if(authToken)boot();else $('loginScreen').classList.remove('hidden');
